import { __decorate } from 'tslib';
import { attachShadowTemplate, customElement } from '@tylertech/forge-core';
import { BaseComponent } from '../../core/base/base-component.js';
import { VIEW_CONSTANTS } from './view-constants.js';
import template from './view.html.js';
import styles from './view.scss.js';

/**
 * @summary Represents a single view content area within a view-switcher for organizing and displaying content sections.
 *
 * @tag forge-view
 */
let ViewComponent = class ViewComponent extends BaseComponent {
  constructor() {
    super();
    attachShadowTemplate(this, template, styles);
  }
};
ViewComponent = __decorate([customElement({
  name: VIEW_CONSTANTS.elementName
})], ViewComponent);
export { ViewComponent };